package com.example.rokidkeyboardbridge;
public class MotionScenesTest {
 public static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}
 public static void main(String[] args){CharacterMotionTuning.parts(2,2,2,2);CharacterMotionTuning.naturalPoses=true;
 for(FullBodyPoseCatalog.Pose p:FullBodyPoseCatalog.ALL){ok(!ConversationImageMetadata.scene(p).isEmpty()&&!ConversationImageMetadata.avoid(p).isEmpty(),"scene and exclusions: "+p.id);for(FullBodyPoseCatalog.Kind kind:FullBodyPoseCatalog.Kind.values()){int chosen=FullBodyPoseCatalog.select(kind,3,p.id,1);ok(FullBodyMotionPolicy.isSeated(chosen)==p.seated,"semantic response never changes posture: "+p.id+" "+kind);}}
 ok(FullBodyPoseCatalog.select(FullBodyPoseCatalog.Kind.JOY,3,168,2)==168,"missing seated joy keeps seated base");ok(ConversationImageMetadata.score(FullBodyPoseCatalog.ALL[1],FullBodyPoseCatalog.Kind.JOY,1,168)<0,"standing smile excluded for seated request");
 for(int kind=0;kind<8;kind++)for(int variant=0;variant<3;variant++)for(long age:new long[]{-1,0,450,900,1800,2800,4400,10000}){float nod=ConversationMicroMotion.nod(kind,age,variant),tilt=ConversationMicroMotion.tilt(kind,age,variant),gaze=ConversationMicroMotion.gaze(kind,age,variant);ok(Float.isFinite(nod)&&Math.abs(nod)<.006f&&Float.isFinite(tilt)&&Math.abs(tilt)<1&&Float.isFinite(gaze)&&Math.abs(gaze)<.004f,"bounded finite movement");if(age<0||age>=4400)ok(nod==0&&tilt==0&&gaze==0,"event returns exactly to base");}
 ok(ConversationMicroMotion.idleAge(25000,10000,0,false,false)==1000,"idle available after fourteen seconds");for(int mode:new int[]{1,2})ok(ConversationMicroMotion.idleAge(25000,10000,mode,false,false)<0,"busy mode blocks idle");ok(ConversationMicroMotion.idleAge(25000,10000,0,false,true)<0&&ConversationMicroMotion.idleAge(25000,10000,0,true,false)<0,"quiet or refused blocks idle");CharacterMotionTuning.naturalPoses=false;ok(ConversationMicroMotion.idleAge(25000,10000,0,false,false)<0,"natural off respected");CharacterMotionTuning.naturalPoses=true;
 CharacterGestureLife life=new CharacterGestureLife();life.event(CharacterGestureLife.LISTEN,10000);float first=life.nod(10900,0,false);life.event(CharacterGestureLife.LISTEN,20000);float second=life.nod(20900,0,false);ok(first!=second||life.nod(22000,0,false)!=0,"event has bounded variation");life.event(CharacterGestureLife.SETTLE,10000);ok(life.tilt(25500,0,false)!=0,"idle reaches actual life pipeline");ok(life.moving(25500),"idle requests fast frames only during gesture");life.tilt(25500,0,true);ok(!life.moving(25500),"quiet removes idle fast frames");life.clear();ok(life.tilt(25500,0,false)==0&&!life.moving(25500),"refusal clears and blocks gesture");
 System.out.println("PASS "+n+" motion and image-scene metadata checks");}
}
